// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { PropertyName } from '@stdlib/types/object';
import { AccessorArrayLike } from '@stdlib/types/array';

/**
* Interface describing `pluck`.
*/
interface Pluck {
	/**
	* Extracts a property value from elements in an input object array and assigns results to elements in a new output array.
	*
	* @param x - input array object
	* @param prop - property to access
	* @returns output array object
	*
	* @example
	* var toAccessorArray = require( '@stdlib/array/to-accessor-array' );
	*
	* var x = [
	*     {
	*         'a': 1,
	*         'b': 2
	*     },
	*     {
	*         'a': 0.5,
	*         'b': 3
	*     }
	* ];
	*
	* var out = pluck( toAccessorArray( x ), 'a' );
	* // x => [ 1, 0.5 ]
	*/
	( x: AccessorArrayLike<any>, prop: PropertyName ): AccessorArrayLike<any>;

	/**
	* Extracts a property value from elements in an input object array and assigns results to elements in a new output array.
	*
	* @param x - input array
	* @param prop - property to access
	* @returns output array
	*
	* @example
	* var x = [
	*     {
	*         'a': 1,
	*         'b': 2
	*     },
	*     {
	*         'a': 0.5,
	*         'b': 3
	*     }
	* ];
	*
	* var out = pluck( x, 'a' );
	* // returns [ 1, 0.5 ]
	*/
	( x: Array<any>, prop: PropertyName ): Array<any>;

	/**
	* Extracts a property value from elements in an input object array and assigns results to elements in an output array.
	*
	* @param x - input array object
	* @param prop - property to access
	* @param out - output array object
	* @param stride - stride length for output array
	* @param offset - starting index for output array
	* @returns output array object
	*
	* @example
	* var toAccessorArray = require( '@stdlib/array/to-accessor-array' );
	*
	* var x = [
	*     {
	*         'a': 1,
	*         'b': 2
	*     },
	*     {
	*         'a': 0.5,
	*         'b': 3
	*     }
	* ];
	* var y = [ 0, 0 ]
	*
	* var out = pluck.assign( toAccessorArray( x ), 'a', toAccessorArray( y ), 1, 0 );
	* // y => [ 1, 0.5 ]
	*/
	assign( x: AccessorArrayLike<any>, prop: PropertyName, out: AccessorArrayLike<any>, stride: number, offset: number ): AccessorArrayLike<any>;

	/**
	* Extracts a property value from elements in an input object array and assigns results to elements in an output array.
	*
	* @param x - input array
	* @param prop - property to access
	* @param out - output array
	* @param stride - stride length for output array
	* @param offset - starting index for output array
	* @returns output array
	*
	* @example
	* var x = [
	*     {
	*         'a': 1,
	*         'b': 2
	*     },
	*     {
	*         'a': 0.5,
	*         'b': 3
	*     }
	* ];
	* var y = [ 0, 0 ]
	*
	* var out = pluck.assign( x, 'a', y, 1, 0 );
	* // returns [ 1, 0.5 ]
	*
	* var bool = ( out === y );
	* // returns true
	*/
	assign( x: Array<any>, prop: PropertyName, out: Array<any>, stride: number, offset: number ): Array<any>;
}

/**
* Extracts a property value from elements in an input object array and assigns results to elements in a new output array.
*
* @param x - input array
* @param prop - property to access
* @returns output array
*
* @example
* var x = [
*     {
*         'a': 1,
*         'b': 2
*     },
*     {
*         'a': 0.5,
*         'b': 3
*     }
* ];
*
* var result = pluck( x, 'a' );
* // returns [ 1, 0.5 ]
*
* @example
* var x = [
*     {
*         'a': 1,
*         'b': 2
*     },
*     {
*         'a': 0.5,
*         'b': 3
*     }
* ];
* var y = [ 0, 0 ]
*
* var out = pluck.assign( x, 'a', y, 1, 0 );
* // returns [ 1, 0.5 ]
*
* var bool = ( out === y );
* // returns true
*/
declare var pluck: Pluck;


// EXPORTS //

export = pluck;
